 class eventclass_tarea_entregas  extends eventsBase
{
	function __construct()
	{
	// fill list of events
		$this->events["BeforeQueryList"]=true;

		$this->events["BeforeAdd"]=true;


	}

//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		if ($_SESSION["rol"] == 'Docente') {
    $strWhereClause = whereAdd($strWhereClause, "tarea_id IN (SELECT t.id FROM tareas t INNER JOIN cursos c ON c.id = t.curso_id WHERE c.profesor_id = " . intval($_SESSION["profesor_id"]) . ")");
} elseif ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "estudiante_id = " . intval($_SESSION["estudiante_id"]));
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$values["fecha_entrega"] = date("Y-m-d H:i:s");

// Si es Alumno, vincular automáticamente su ID
if ($_SESSION["rol"] == "Alumno" && intval($_SESSION["estudiante_id"]) > 0) {
    $values["estudiante_id"] = intval($_SESSION["estudiante_id"]);
}

$tarea_id = intval($values["tarea_id"]);
$rsT = DB::Query("SELECT fecha_entrega FROM tareas WHERE id = " . $tarea_id);
if ($rT = $rsT->fetchAssoc()) {
    if (!empty($rT["fecha_entrega"]) && $values["fecha_entrega"] > $rT["fecha_entrega"]) {
        $com = !empty($values["comentario"]) ? $values["comentario"] . " " : "";
        $values["comentario"] = $com . "[Entregado con retraso el " . date("d/m/Y H:i") . "]";
    }
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



